1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import {searchArticles} from './search.mjs';
4	const rows=[{id:'a',title:'Agent memory',title_zh:'智能体记忆',summary:'Context engineering'}, {id:'b',title:'GPU serving',summary_zh:'智能体推理服务'}, {id:'a',title:'Agent memory duplicate'}];
5	test('matches case-insensitively',()=>assert.equal(searchArticles(rows,'MEMORY')[0].id,'a'));
6	test('searches translated titles and summaries',()=>assert.deepEqual(searchArticles(rows,'智能体').map(row=>row.id),['a','b']));
7	test('normalizes full-width Unicode query characters',()=>assert.equal(searchArticles(rows,'ＡＧＥＮＴ')[0]?.id,'a'));
8	test('deduplicates by ID, preserving the first matching row',()=>assert.deepEqual(searchArticles(rows,'agent').map(row=>row.id),['a']));
9	test('skips malformed rows and rows without a nonempty string ID',()=>assert.deepEqual(searchArticles([null,{},...rows],'agent').map(row=>row.id),['a']));
10	test('returns no rows for an empty or whitespace query',()=>assert.deepEqual(searchArticles(rows,'  '),[]));
11	test('does not modify source rows',()=>{const snapshot=JSON.stringify(rows);searchArticles(rows,'agent');assert.equal(JSON.stringify(rows),snapshot);});
